'use strict';
(()=>{
 const section=document.querySelector('#home'),art=section.querySelector('.hero-art'),shell=document.createElement('div');shell.className='hero-shell';while(section.firstChild)shell.append(section.firstChild);section.append(shell);
 const views=[['13','The room'],['02','Entrance'],['11','Kitchen'],['07','Wash station']];
 art.innerHTML=`<div class="hero-stage" aria-label="Scroll-driven 3D property photographs"><div class="hero-stage-label">YOUR FLAT. FOUR PERSPECTIVES.</div><div class="hero-floor" aria-hidden="true"></div><div class="hero-object">${views.map(([id,label])=>`<figure class="hero-face"><img src="assets/${id}.webp" alt="${label} — cleaned property preview" width="750" height="1000"><figcaption><span>${label.toUpperCase()}</span><span>702</span></figcaption></figure>`).join('')}</div><div class="hero-controls"><button id="hero-prev" aria-label="Previous hero photograph">←</button><span class="hero-readout"></span><button id="hero-next" aria-label="Next hero photograph">→</button><button class="hero-pause" aria-pressed="false">Reduce motion</button></div><div class="hero-track" aria-hidden="true"><span></span></div></div>`;
 const cards=[...art.querySelectorAll('.hero-face')],readout=art.querySelector('.hero-readout'),toggle=art.querySelector('.hero-pause');let frame=0,index=0;
 function render(){frame=0;const travel=section.offsetHeight-shell.offsetHeight,progress=Math.max(0,Math.min(1,-section.getBoundingClientRect().top/Math.max(1,travel))),position=progress*3,reduced=document.body.classList.contains('calm');index=Math.round(position);
 cards.forEach((card,i)=>{const d=i-position;card.style.transform=reduced?'none':`translate3d(${d*(innerWidth<=900?105:180)}px,${Math.abs(d)*-15}px,${-Math.abs(d)*230}px) rotateY(${-12-d*22}deg) rotateZ(${d*3}deg)`;card.style.opacity=reduced?(i===index?'1':'0'):String(Math.max(0,d<0?1+d*1.6:1-d*.38));card.style.visibility=reduced?(i===index?'visible':'hidden'):(Math.abs(d)>2||d<-.65?'hidden':'visible');card.setAttribute('aria-hidden',String(i!==index));card.style.zIndex=String(10-i);});
 readout.textContent=`0${index+1} / ${views[index][1]}`;art.querySelector('.hero-track span').style.transform=`scaleX(${progress})`;toggle.textContent=reduced?'Enable motion':'Reduce motion';toggle.setAttribute('aria-pressed',String(reduced));}
 function schedule(){if(!frame)frame=requestAnimationFrame(render);}
 function step(delta){const next=Math.max(0,Math.min(3,index+delta));scrollTo({top:section.getBoundingClientRect().top+scrollY+next/3*(section.offsetHeight-shell.offsetHeight),behavior:document.body.classList.contains('calm')?'instant':'smooth'});}
 document.querySelector('#hero-prev').onclick=()=>step(-1);document.querySelector('#hero-next').onclick=()=>step(1);toggle.onclick=()=>document.querySelector('#motion-toggle').click();addEventListener('scroll',schedule,{passive:true});addEventListener('resize',schedule,{passive:true});new ResizeObserver(schedule).observe(shell);new MutationObserver(schedule).observe(document.body,{attributes:true,attributeFilter:['class']});render();
})();
